-- Best-track LineStrings for /v1/hits.
UPDATE catalog.storm s SET track = t.line FROM (
  SELECT sid, ST_MakeLine(position::geometry ORDER BY observed_at)::geography AS line
  FROM catalog.storm_fix GROUP BY sid HAVING count(*) > 1) t
WHERE t.sid = s.sid;
